--
-- Table structure for table `cliente_limites`
--

DROP TABLE IF EXISTS `cliente_limites`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cliente_limites` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `limite_credito` decimal(10,2) NOT NULL DEFAULT '100.00',
  `limite_utilizado` decimal(10,2) NOT NULL DEFAULT '0.00',
  `limite_disponivel` decimal(10,2) NOT NULL DEFAULT '100.00',
  `data_ultimo_ajuste` timestamp NULL DEFAULT NULL,
  `motivo_ultimo_ajuste` varchar(255) DEFAULT NULL,
  `ativo` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
