/*!50003 CREATE*/ /*!50017 DEFINER=`sacolinhas_user`@`%`*/ /*!50003 TRIGGER `atualizar_limite_disponivel` BEFORE UPDATE ON `cliente_limites` FOR EACH ROW BEGIN
    IF NEW.limite_credito != OLD.limite_credito THEN
        SET NEW.limite_disponivel = NEW.limite_credito - NEW.limite_utilizado;
        SET NEW.data_ultimo_ajuste = CURRENT_TIMESTAMP;
    END IF;
END */;;
