/*!50003 CREATE*/ /*!50017 DEFINER=`sacolinhas_user`@`%`*/ /*!50003 TRIGGER `trg_clube_mensalidades_au` AFTER UPDATE ON `clube_mensalidades` FOR EACH ROW BEGIN
    DECLARE v_mes_ano VARCHAR(7);
    DECLARE v_grupo_id BIGINT UNSIGNED DEFAULT NULL;
    
    
    IF NEW.status_pagamento = 'pago' AND DAY(NEW.pago_em) <= 25
       AND (OLD.status_pagamento != 'pago' OR DAY(OLD.pago_em) > 25 OR OLD.pago_em IS NULL) THEN
        SET v_mes_ano = CONCAT(NEW.competencia_ano, '-', LPAD(NEW.competencia_mes, 2, '0'));
        CALL atualizar_pontuacoes_user(NEW.user_id, v_mes_ano);
        SELECT gm.grupo_id INTO v_grupo_id FROM grupo_membros gm WHERE gm.user_id = NEW.user_id LIMIT 1;
        IF v_grupo_id IS NOT NULL THEN CALL atualizar_pontuacoes_grupo(v_grupo_id, v_mes_ano); END IF;
    
    ELSEIF OLD.status_pagamento = 'pago' AND DAY(OLD.pago_em) <= 25
           AND (NEW.status_pagamento != 'pago' OR DAY(NEW.pago_em) > 25) THEN
        SET v_mes_ano = CONCAT(OLD.competencia_ano, '-', LPAD(OLD.competencia_mes, 2, '0'));
        CALL atualizar_pontuacoes_user(NEW.user_id, v_mes_ano);
        SELECT gm.grupo_id INTO v_grupo_id FROM grupo_membros gm WHERE gm.user_id = NEW.user_id LIMIT 1;
        IF v_grupo_id IS NOT NULL THEN CALL atualizar_pontuacoes_grupo(v_grupo_id, v_mes_ano); END IF;
    END IF;
END */;;
