/*!50003 CREATE*/ /*!50017 DEFINER=`sacolinhas_user`@`%`*/ /*!50003 TRIGGER `tr_items_pedido_ai_recalc_pedido_total` AFTER INSERT ON `items_pedido` FOR EACH ROW BEGIN
  UPDATE pedidos p
  SET p.valor_total =
      (SELECT COALESCE(SUM(ip.preco_unitario),0)
         FROM items_pedido ip
        WHERE ip.pedido_id = NEW.pedido_id
          AND ip.status_item = 'ativo')
      + COALESCE(p.valor_frete,0)
      - COALESCE(p.valor_desconto,0)
  WHERE p.id = NEW.pedido_id;
END */;;
DELIMITER ;
