/*!50003 CREATE*/ /*!50017 DEFINER=`sacolinhas_user`@`%`*/ /*!50003 TRIGGER `trg_items_pedido_ai` AFTER INSERT ON `items_pedido` FOR EACH ROW BEGIN
    DECLARE v_user_id BIGINT UNSIGNED;
    DECLARE v_mes_ano VARCHAR(7);
    DECLARE v_grupo_id BIGINT UNSIGNED DEFAULT NULL;

    IF NEW.status_item = 'ativo' THEN
        SELECT p.user_id, DATE_FORMAT(p.data_pedido, '%Y-%m')
        INTO v_user_id, v_mes_ano
        FROM pedidos p WHERE p.id = NEW.pedido_id;

        IF v_user_id IS NOT NULL THEN
            CALL atualizar_pontuacoes_user(v_user_id, v_mes_ano);

            SELECT gm.grupo_id INTO v_grupo_id
            FROM grupo_membros gm WHERE gm.user_id = v_user_id LIMIT 1;

            IF v_grupo_id IS NOT NULL THEN
                CALL atualizar_pontuacoes_grupo(v_grupo_id, v_mes_ano);
            END IF;
        END IF;
    END IF;
END */;;
DELIMITER ;
