CREATE TABLE `pedidos` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `numero_pedido` varchar(20) NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `live_id` bigint unsigned DEFAULT NULL,
  `data_pedido` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `status_pedido` enum('pendente','processando','pago','enviado','cancelado','concluido') NOT NULL DEFAULT 'pendente',
  `valor_total` decimal(10,2) NOT NULL DEFAULT '0.00',
  `valor_frete` decimal(8,2) NOT NULL DEFAULT '0.00',
  `valor_desconto` decimal(8,2) NOT NULL DEFAULT '0.00',
  `forma_pagamento` enum('pix','cartao_credito','cartao_debito','boleto','dinheiro','transferencia') DEFAULT NULL,
  `status_pagamento` enum('pendente','aprovado','rejeitado','estornado') NOT NULL DEFAULT 'pendente',
  `endereco_entrega` text,
  `cep_entrega` varchar(10) DEFAULT NULL,
  `cidade_entrega` varchar(255) DEFAULT NULL,
  `estado_entrega` varchar(2) DEFAULT NULL,
  `codigo_rastreamento` varchar(50) DEFAULT NULL,
  `data_envio` timestamp NULL DEFAULT NULL,
  `data_entrega_prevista` date DEFAULT NULL,
  `data_entrega_realizada` timestamp NULL DEFAULT NULL,
  `observacoes` text,
  `cupom_desconto` varchar(50) DEFAULT NULL,
  `origem_pedido` enum('live','site','whatsapp','instagram') NOT NULL DEFAULT 'live',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `numero_pedido_unique` (`numero_pedido`),
  KEY `pedidos_user_id_foreign` (`user_id`),
  KEY `pedidos_live_id_foreign` (`live_id`),
  KEY `pedidos_status_pedido_index` (`status_pedido`),
  KEY `pedidos_data_pedido_index` (`data_pedido`),
  KEY `idx_pedidos_user_status_data` (`user_id`,`status_pedido`,`data_pedido`),
  CONSTRAINT `pedidos_live_id_foreign` FOREIGN KEY (`live_id`) REFERENCES `lives` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pedidos_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=302 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
