--
-- Table structure for table `whatsapp_messages`
--

DROP TABLE IF EXISTS `whatsapp_messages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `whatsapp_messages` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned DEFAULT NULL,
  `live_id` bigint unsigned DEFAULT NULL,
  `pedido_id` bigint unsigned DEFAULT NULL,
  `direction` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('pending','queued','sent','delivered','read','failed','undelivered','received') COLLATE utf8mb4_unicode_ci DEFAULT 'pending',
  `error_code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `message_sid` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `account_sid` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `from` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `to` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `body` text COLLATE utf8mb4_unicode_ci,
  `num_media` int unsigned DEFAULT NULL,
  `media_url` text COLLATE utf8mb4_unicode_ci,
  `media_content_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `message_type` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `button_text` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `button_payload` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `profile_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `wa_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `raw_payload` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `status_updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `delivery_timestamp` timestamp NULL DEFAULT NULL,
  `read_timestamp` timestamp NULL DEFAULT NULL,
  `failed_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `retry_count` int unsigned DEFAULT '0',
  `is_confirmed` tinyint(1) DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_whatsapp_messages_message_sid` (`message_sid`),
  KEY `idx_whatsapp_messages_user_id` (`user_id`),
  KEY `idx_whatsapp_messages_live_id` (`live_id`),
  KEY `idx_whatsapp_messages_pedido_id` (`pedido_id`),
  KEY `idx_whatsapp_messages_direction` (`direction`),
  KEY `idx_whatsapp_messages_status` (`status`),
  KEY `idx_whatsapp_messages_message_sid` (`message_sid`),
  KEY `idx_whatsapp_messages_from` (`from`),
  KEY `idx_whatsapp_messages_to` (`to`),
  KEY `idx_whatsapp_messages_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=5386 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

