/*!50001 DROP VIEW IF EXISTS `vw_grupo_em_dia`*/;
/*!50001 SET @saved_cs_client          = @@character_set_client */;
/*!50001 SET @saved_cs_results         = @@character_set_results */;
/*!50001 SET @saved_col_connection     = @@collation_connection */;
/*!50001 SET character_set_client      = latin1 */;
/*!50001 SET character_set_results     = latin1 */;
/*!50001 SET collation_connection      = latin1_swedish_ci */;
/*!50001 CREATE ALGORITHM=UNDEFINED */
/*!50013 DEFINER=`sacolinhas_user`@`%` SQL SECURITY DEFINER */
/*!50001 VIEW `vw_grupo_em_dia` AS select `g`.`id` AS `grupo_id`,concat(`cm`.`competencia_ano`,'-',lpad(`cm`.`competencia_mes`,2,'0')) AS `mes_ano`,((count((case when ((`cm`.`status_pagamento` = 'pago') and (dayofmonth(`cm`.`pago_em`) <= 25)) then 1 end)) * 100.0) / count(`gm`.`user_id`)) AS `percentual_em_dia`,(case when (count((case when ((`cm`.`status_pagamento` = 'pago') and (dayofmonth(`cm`.`pago_em`) <= 25)) then 1 end)) = count(`gm`.`user_id`)) then 1 else 0 end) AS `grupo_100_em_dia` from ((`grupos` `g` join `grupo_membros` `gm` on((`g`.`id` = `gm`.`grupo_id`))) join `clube_mensalidades` `cm` on((`gm`.`user_id` = `cm`.`user_id`))) group by `g`.`id`,`mes_ano` */;
/*!50001 SET character_set_client      = @saved_cs_client */;
/*!50001 SET character_set_results     = @saved_cs_results */;
/*!50001 SET collation_connection      = @saved_col_connection */;

