/*!50001 SET character_set_results     = latin1 */;
/*!50001 SET collation_connection      = latin1_swedish_ci */;
/*!50001 CREATE ALGORITHM=UNDEFINED */
/*!50013 DEFINER=`sacolinhas_user`@`%` SQL SECURITY DEFINER */
/*!50001 VIEW `vw_pontos_desafios_user` AS select `pontos_desafios`.`user_id` AS `user_id`,`pontos_desafios`.`mes_ano` AS `mes_ano`,coalesce(sum(`pontos_desafios`.`pontos`),0) AS `pontos_desafios` from `pontos_desafios` group by `pontos_desafios`.`user_id`,`pontos_desafios`.`mes_ano` */;
/*!50001 SET character_set_client      = @saved_cs_client */;
